import sys, math, heapq, bisect
from collections import Counter, deque
D = sys.stdin.read().split()
h,w=map(int,D[:2]); g=[list(s) for s in D[2:]]; best=0
for i in range(h):
    for j in range(w):
        if g[i][j]!="1": continue
        g[i][j]="0"; q=[(i,j)]; area=0
        while q:
            r,c=q.pop(); area+=1
            for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
                if 0<=rr<h and 0<=cc<w and g[rr][cc]=="1": g[rr][cc]="0"; q.append((rr,cc))
        best=max(best,area)
print(best)

