import sys, math, heapq, bisect
from collections import Counter, deque
D = sys.stdin.read().split()
data=list(map(int,D)); n,q=data[:2]; e=data[2:2*n]; g=[[] for _ in range(n+1)]
for u,v in zip(e[::2],e[1::2]): g[u].append(v); g[v].append(u)
d=[0]*(n+1); p=[0]*(n+1); order=[1]
for u in order:
    for v in g[u]:
        if v!=p[u]: p[v]=u; d[v]=d[u]+1; order.append(v)
up=[p]
for _ in range(n.bit_length()-1):
    prev=up[-1]; up.append([prev[x] for x in prev])
for i in range(2*n,len(data),2):
    u,v=data[i:i+2]
    if d[u]<d[v]: u,v=v,u
    delta=d[u]-d[v]
    for k,p in enumerate(up):
        if (delta>>k)&1: u=p[u]
    if u!=v:
        for p in reversed(up):
            if p[u]!=p[v]: u,v=p[u],p[v]
        u=up[0][u]
    print(u)
